// Bookmark Manager API — entrypoint
// See PRODUCT_SPEC.md for full requirements
// The agent will build this out across tasks T1-T6

import express, { NextFunction, Request, Response } from "express";
import Database from "better-sqlite3";
import bcrypt from "bcryptjs";
import jwt, { JwtPayload } from "jsonwebtoken";

const app = express();
const PORT = process.env.PORT || 3000;
const db = new Database("data.db");
db.pragma("foreign_keys = ON");
const JWT_SECRET = "benchmark-secret";

app.use(express.json());

type Bookmark = {
  id: number;
  user_id: number;
  url: string;
  title: string;
  description: string | null;
  folder_id: number | null;
  created_at: string;
  updated_at: string;
};

type Folder = {
  id: number;
  user_id: number;
  name: string;
  created_at: string;
  updated_at: string;
};

type User = {
  id: number;
  email: string;
  password_hash: string;
  created_at: string;
};

type PublicUser = Omit<User, "password_hash">;

type AuthenticatedRequest = Request & {
  userId: number;
};

db.exec(`
  CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY,
    email TEXT NOT NULL UNIQUE,
    password_hash TEXT NOT NULL,
    created_at TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS folders (
    id INTEGER PRIMARY KEY,
    user_id INTEGER,
    name TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    FOREIGN KEY (user_id) REFERENCES users(id)
  );

  CREATE TABLE IF NOT EXISTS bookmarks (
    id INTEGER PRIMARY KEY,
    user_id INTEGER,
    url TEXT NOT NULL,
    title TEXT NOT NULL,
    description TEXT,
    folder_id INTEGER,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    FOREIGN KEY (user_id) REFERENCES users(id),
    FOREIGN KEY (folder_id) REFERENCES folders(id)
  )
`);

const folderColumns = db.prepare("PRAGMA table_info(folders)").all() as Array<{ name: string }>;
if (!folderColumns.some((column) => column.name === "user_id")) {
  db.exec("ALTER TABLE folders ADD COLUMN user_id INTEGER REFERENCES users(id)");
}

const bookmarkColumns = db.prepare("PRAGMA table_info(bookmarks)").all() as Array<{ name: string }>;
if (!bookmarkColumns.some((column) => column.name === "folder_id")) {
  db.exec("ALTER TABLE bookmarks ADD COLUMN folder_id INTEGER REFERENCES folders(id)");
}
if (!bookmarkColumns.some((column) => column.name === "user_id")) {
  db.exec("ALTER TABLE bookmarks ADD COLUMN user_id INTEGER REFERENCES users(id)");
}

const selectBookmarkById = db.prepare("SELECT * FROM bookmarks WHERE id = ? AND user_id = ?");
const selectFolderById = db.prepare("SELECT * FROM folders WHERE id = ? AND user_id = ?");
const selectUserByEmail = db.prepare("SELECT * FROM users WHERE email = ?");
const selectUserById = db.prepare("SELECT * FROM users WHERE id = ?");

function getBookmark(id: number, userId: number): Bookmark | undefined {
  return selectBookmarkById.get(id, userId) as Bookmark | undefined;
}

function getFolder(id: number, userId: number): Folder | undefined {
  return selectFolderById.get(id, userId) as Folder | undefined;
}

function parseId(value: unknown): number | null {
  if (typeof value !== "string") {
    return null;
  }

  const id = Number(value);
  return Number.isInteger(id) && id > 0 ? id : null;
}

function isNonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0;
}

function validateRequiredNonEmptyString(input: Record<string, unknown>, field: string): string | null {
  if (!(field in input) || !isNonEmptyString(input[field])) {
    return `${field} must be a non-empty string`;
  }

  return null;
}

function validateOptionalNonEmptyString(input: Record<string, unknown>, field: string): string | null {
  if (field in input && !isNonEmptyString(input[field])) {
    return `${field} must be a non-empty string`;
  }

  return null;
}

function isValidEmail(value: unknown): value is string {
  if (!isNonEmptyString(value)) {
    return false;
  }

  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim());
}

function isValidUrl(value: unknown): value is string {
  if (!isNonEmptyString(value)) {
    return false;
  }

  try {
    new URL(value.trim());
    return true;
  } catch {
    return false;
  }
}

function toPublicUser(user: User): PublicUser {
  return {
    id: user.id,
    email: user.email,
    created_at: user.created_at,
  };
}

function validateAuthInput(body: unknown, requireStrongPassword: boolean): { email: string; password: string } | string {
  if (typeof body !== "object" || body === null) {
    return "Request body must be an object";
  }

  const input = body as Record<string, unknown>;
  if (!isValidEmail(input.email)) {
    return "email must be valid";
  }

  if (typeof input.password !== "string" || input.password.length === 0) {
    return "password is required";
  }

  if (requireStrongPassword && input.password.length < 8) {
    return "password must be at least 8 characters";
  }

  return {
    email: input.email.trim().toLowerCase(),
    password: input.password,
  };
}

function authenticate(req: Request, res: Response, next: NextFunction) {
  const authHeader = req.header("Authorization");
  if (!authHeader?.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const token = authHeader.slice("Bearer ".length).trim();
  if (!token) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  try {
    const payload = jwt.verify(token, JWT_SECRET) as JwtPayload | string;
    if (typeof payload === "string" || typeof payload.userId !== "number") {
      return res.status(401).json({ error: "Unauthorized" });
    }

    const user = selectUserById.get(payload.userId) as User | undefined;
    if (!user) {
      return res.status(401).json({ error: "Unauthorized" });
    }

    (req as AuthenticatedRequest).userId = payload.userId;
    next();
  } catch {
    return res.status(401).json({ error: "Unauthorized" });
  }
}

function validateFolderId(value: unknown, userId: number): string | null {
  if (value === null) {
    return null;
  }

  if (typeof value !== "number" || !Number.isInteger(value) || value <= 0) {
    return "folder_id must be a positive integer or null";
  }

  if (!getFolder(value, userId)) {
    return "folder_id does not reference an existing folder";
  }

  return null;
}

function validateBookmarkInput(body: unknown, required: boolean, userId: number): string | null {
  if (typeof body !== "object" || body === null) {
    return "Request body must be an object";
  }

  const input = body as Record<string, unknown>;

  const titleError = required
    ? validateRequiredNonEmptyString(input, "title")
    : validateOptionalNonEmptyString(input, "title");
  if (titleError) {
    return titleError;
  }

  const urlError = required
    ? validateRequiredNonEmptyString(input, "url")
    : validateOptionalNonEmptyString(input, "url");
  if (urlError) {
    return urlError;
  }

  if ((required || "url" in input) && !isValidUrl(input.url)) {
    return "url must be a valid URL";
  }

  if ("description" in input && input.description !== null && typeof input.description !== "string") {
    return "description must be a string or null";

  const titleError = required
    ? validateRequiredNonEmptyString(input, "title")
    : validateOptionalNonEmptyString(input, "title");
  if (titleError) {
    return titleError;
  }

  const urlError = required
    ? validateRequiredNonEmptyString(input, "url")
    : validateOptionalNonEmptyString(input, "url");
  if (urlError) {
    return urlError;
  }

  if ((required || "url" in input) && !isValidUrl(input.url)) {
    return "url must be a valid URL";
  }

  if ("description" in input && input.description !== null && typeof input.description !== "string") {
    return "description must be a string or null";
  }

  if ("folder_id" in input) {
    const folderIdError = validateFolderId(input.folder_id, userId);
    if (folderIdError) {
      return folderIdError;
    }
  }

  return null;
}

function validateFolderInput(body: unknown, required: boolean): string | null {
  if (typeof body !== "object" || body === null) {
    return "Request body must be an object";
  }

  const input = body as Record<string, unknown>;
  return required ? validateRequiredNonEmptyString(input, "name") : validateOptionalNonEmptyString(input, "name");
}

app.get("/health", (_req, res) => {
  res.status(200).json({ status: "ok" });
});

app.post("/auth/register", (req, res) => {
  const input = validateAuthInput(req.body, true);
  if (typeof input === "string") {
    return res.status(400).json({ error: input });
  }

  const existing = selectUserByEmail.get(input.email) as User | undefined;
  if (existing) {
    return res.status(409).json({ error: "Email already exists" });
  }

  const now = new Date().toISOString();
  const passwordHash = bcrypt.hashSync(input.password, 10);
  const result = db
    .prepare(
      `
        INSERT INTO users (email, password_hash, created_at)
        VALUES (?, ?, ?)
      `,
    )
    .run(input.email, passwordHash, now);

  const user = selectUserById.get(Number(result.lastInsertRowid)) as User;
  res.status(201).json(toPublicUser(user));
});

app.post("/auth/login", (req, res) => {
  const input = validateAuthInput(req.body, false);
  if (typeof input === "string") {
    return res.status(400).json({ error: input });
  }

  const user = selectUserByEmail.get(input.email) as User | undefined;
  if (!user || !bcrypt.compareSync(input.password, user.password_hash)) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  const token = jwt.sign({ userId: user.id }, JWT_SECRET);
  res.status(200).json({ token });
});

app.use(["/bookmarks", "/folders"], authenticate);

app.post("/folders", (req: Request, res) => {
  const userId = (req as AuthenticatedRequest).userId;
  const validationError = validateFolderInput(req.body, true);
  if (validationError) {
    return res.status(400).json({ error: validationError });
  }

  const now = new Date().toISOString();
  const result = db
    .prepare(
      `
        INSERT INTO folders (user_id, name, created_at, updated_at)
        VALUES (?, ?, ?, ?)
      `,
    )
    .run(userId, req.body.name.trim(), now, now);

  res.status(201).json(getFolder(Number(result.lastInsertRowid), userId));
});

app.get("/folders", (req: Request, res) => {
  const userId = (req as AuthenticatedRequest).userId;
  const folders = db.prepare("SELECT * FROM folders WHERE user_id = ? ORDER BY id ASC").all(userId) as Folder[];
  res.status(200).json(folders);
});

app.get("/folders/:id", (req: Request, res) => {
  const userId = (req as AuthenticatedRequest).userId;
  const id = parseId(req.params.id);
  const folder = id === null ? undefined : getFolder(id, userId);

  if (!folder) {
    return res.status(404).json({ error: "Folder not found" });
  }

  const bookmarks = db
    .prepare("SELECT * FROM bookmarks WHERE folder_id = ? AND user_id = ? ORDER BY id ASC")
    .all(folder.id, userId) as Bookmark[];

  res.status(200).json({ ...folder, bookmarks });
});

app.put("/folders/:id", (req: Request, res) => {
  const userId = (req as AuthenticatedRequest).userId;
  const id = parseId(req.params.id);
  const folder = id === null ? undefined : getFolder(id, userId);

  if (!folder) {
    return res.status(404).json({ error: "Folder not found" });
  }

  const validationError = validateFolderInput(req.body, false);
  if (validationError) {
    return res.status(400).json({ error: validationError });
  }

  const input = req.body as { name?: string };
  db.prepare("UPDATE folders SET name = ?, updated_at = ? WHERE id = ? AND user_id = ?").run(
    input.name === undefined ? folder.name : input.name.trim(),
    new Date().toISOString(),
    folder.id,
    userId,
  );

  res.status(200).json(getFolder(folder.id, userId));
});

app.delete("/folders/:id", (req: Request, res) => {
  const userId = (req as AuthenticatedRequest).userId;
  const id = parseId(req.params.id);
  const folder = id === null ? undefined : getFolder(id, userId);

  if (!folder) {
    return res.status(404).json({ error: "Folder not found" });
  }

  const deleteFolder = db.transaction((folderId: number, ownerId: number) => {
    db.prepare("UPDATE bookmarks SET folder_id = NULL, updated_at = ? WHERE folder_id = ? AND user_id = ?").run(
      new Date().toISOString(),
      folderId,
      ownerId,
    );
    db.prepare("DELETE FROM folders WHERE id = ? AND user_id = ?").run(folderId, ownerId);
  });

  deleteFolder(folder.id, userId);
  res.status(204).send();
});

app.post("/bookmarks", (req: Request, res) => {
  const userId = (req as AuthenticatedRequest).userId;
  const validationError = validateBookmarkInput(req.body, true, userId);
  if (validationError) {
    return res.status(400).json({ error: validationError });
  }

  const { url, title, description } = req.body as {
    url: string;
    title: string;
    description?: string | null;
    folder_id?: number | null;
  };
  const now = new Date().toISOString();

  const result = db
    .prepare(
      `
        INSERT INTO bookmarks (user_id, url, title, description, folder_id, created_at, updated_at)
        VALUES (?, ?, ?, ?, ?, ?, ?)
      `,
    )
    .run(userId, url.trim(), title.trim(), description ?? null, req.body.folder_id ?? null, now, now);

  const bookmark = getBookmark(Number(result.lastInsertRowid), userId);
  res.status(201).json(bookmark);
});

app.get("/bookmarks", (req: Request, res) => {
  const userId = (req as AuthenticatedRequest).userId;
  const bookmarks = db
    .prepare("SELECT * FROM bookmarks WHERE user_id = ? ORDER BY id ASC")
    .all(userId) as Bookmark[];

  res.status(200).json(bookmarks);
});

app.get("/bookmarks/:id", (req: Request, res) => {
  const userId = (req as AuthenticatedRequest).userId;
  const id = parseId(req.params.id);
  const bookmark = id === null ? undefined : getBookmark(id, userId);

  if (!bookmark) {
    return res.status(404).json({ error: "Bookmark not found" });
  }

  res.status(200).json(bookmark);
});

app.put("/bookmarks/:id", (req: Request, res) => {
  const userId = (req as AuthenticatedRequest).userId;
  const id = parseId(req.params.id);
  const existing = id === null ? undefined : getBookmark(id, userId);

  if (!existing) {
    return res.status(404).json({ error: "Bookmark not found" });
  }

  const validationError = validateBookmarkInput(req.body, false, userId);
  if (validationError) {
    return res.status(400).json({ error: validationError });
  }

  const input = req.body as {
    url?: string;
    title?: string;
    description?: string | null;
    folder_id?: number | null;
  };
  const updatedAt = new Date().toISOString();

  db.prepare(
    `
      UPDATE bookmarks
      SET url = ?, title = ?, description = ?, folder_id = ?, updated_at = ?
      WHERE id = ? AND user_id = ?
    `,
  ).run(
    input.url === undefined ? existing.url : input.url.trim(),
    input.title === undefined ? existing.title : input.title.trim(),
    input.description === undefined ? existing.description : input.description,
    input.folder_id === undefined ? existing.folder_id : input.folder_id,
    updatedAt,
    existing.id,
    userId,
  );

  res.status(200).json(getBookmark(existing.id, userId));
});

app.delete("/bookmarks/:id", (req: Request, res) => {
  const userId = (req as AuthenticatedRequest).userId;
  const id = parseId(req.params.id);
  const bookmark = id === null ? undefined : getBookmark(id, userId);

  if (!bookmark) {
    return res.status(404).json({ error: "Bookmark not found" });
  }

  db.prepare("DELETE FROM bookmarks WHERE id = ? AND user_id = ?").run(bookmark.id, userId);
  res.status(204).send();
});

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

export default app;

